import @vibe/compiler/codegen/common_base {
  FuncTable, ctor_sorted_index, func_table_user_index_of
}

let user_prefix = 8192

fn user_lookup_names() -> Array[String] {
  let names: Array[String] = []
  let mut i = 0
  while i < user_prefix {
    Array::push(names, String::concat("user_fn_", Int::to_string(i)))
    i = i + 1
  }
  Array::push(names, "Array::with_capacity")
  Array::push(names, "Array::push")
  Array::push(names, "Array::set")
  names
}

let lookup_names = user_lookup_names()

fn user_lookup_table(indexed: Bool) -> FuncTable {
  let (sorted, positions) = if indexed {
    ctor_sorted_index(lookup_names)
  } else {
    ([], [])
  }
  let indices: Array[Int] = []
  let params: Array[Int] = []
  let returns: Array[Int] = []
  let envs: Array[Bool] = []
  let mut i = 0
  while i < Array::length(lookup_names) {
    Array::push(indices, i + 100)
    Array::push(params, 0)
    Array::push(returns, 1)
    Array::push(envs, false)
    i = i + 1
  }
  FuncTable::{
    names: lookup_names,
    indices: indices,
    params: params,
    returns: returns,
    needs_env: envs,
    names_sorted: sorted,
    names_sorted_pos: positions
  }
}

let indexed_table = user_lookup_table(true)
let fallback_table = user_lookup_table(false)
let builtin_queries = ["Array::with_capacity", "Array::push", "Array::set"]
let hit_queries = [
  Array::get(lookup_names, 0),
  Array::get(lookup_names, 4096),
  Array::get(lookup_names, 8191)
]

fn repeated_user_lookups(ft: FuncTable, queries: Array[String]) -> Int {
  let mut sum = 0
  let mut round = 0
  while round < 32 {
    for query in queries {
      sum = sum + func_table_user_index_of(ft, query, user_prefix)
    }
    round = round + 1
  }
  sum
}

bench "user_index/builtin_names" {
  let table = indexed_table
  let queries = builtin_queries
  let before = Profiler::heap_bytes()
  let result = repeated_user_lookups(table, queries)
  let after = Profiler::heap_bytes()
  assert(result == -96)
  assert(after == before)
}

bench "user_index/existing_users" {
  let table = indexed_table
  let queries = hit_queries
  let before = Profiler::heap_bytes()
  let result = repeated_user_lookups(table, queries)
  let after = Profiler::heap_bytes()
  assert(result == 393184)
  assert(after == before)
}

bench "user_index/without_sorted_view" {
  let table = fallback_table
  let queries = builtin_queries
  let before = Profiler::heap_bytes()
  let result = repeated_user_lookups(table, queries)
  let after = Profiler::heap_bytes()
  assert(result == -96)
  assert(after == before)
}

